-- Practice questions for the two new session 10 concepts (eoq_cycle_inventory,
-- safety_stock_reorder_point). Without at least one question each, groupBySession()
-- (src/learn/lib/sessions.ts) never surfaces the topic in the sidebar/search/practice
-- picker -- the concept notes from the prior migration were live in the DB but
-- unreachable in the app until this. Numbers verified independently against the worked
-- examples in the concept notes. GENERATED -- see gen_opmg_s10_questions.py.

begin;

insert into public.learn_questions (id, course_code, type, topic, session, prompt, choices, correct_answer, source, explanation, hint, scenario_id, scenario_order, difficulty, provenance, created_at) values ('opm-f42', 'OPMG', 'formula', 'eoq_cycle_inventory', 10, 'Kristen''s Cookie Co. faces steady demand of 100 dozen cookies/week. Raw material costs $10/dozen, ordering + shipping is $50/order, and the opportunity cost of capital is 20%/year (no separate physical holding cost). What is the EOQ?', '["71 dozen", "228 dozen", "361 dozen", "510 dozen"]'::jsonb, '510 dozen', 'Session 10 — EOQ', 'Annualise first: R = 100 x 52 = 5,200 dozen/year. H = rC = 0.20 x 10 = $2/dozen/year. S = $50. Q* = sqrt(2RS/H) = sqrt(2 x 5,200 x 50 / 2) = sqrt(260,000) ~= 510 dozen. 71 dozen comes from forgetting to annualise R (using the weekly 100 with the annual r). 228 dozen comes from using H = C = $10 instead of H = rC = $2. 361 dozen comes from dropping the factor of 2 inside the square root.', 'Annualise R before plugging into the formula, and don''t confuse C (cost/unit) with H (holding cost/unit/year) -- H = rC only when there''s no separate physical holding cost.', null, null, 2, 'prof_adapted', now()) on conflict (id) do nothing;

insert into public.learn_questions (id, course_code, type, topic, session, prompt, choices, correct_answer, source, explanation, hint, scenario_id, scenario_order, difficulty, provenance, created_at) values ('opm-f43', 'OPMG', 'formula', 'eoq_cycle_inventory', 10, 'Amazon serves total annual demand R for a product from one aggregated warehouse. Adidas serves the identical total demand R by splitting it evenly across 100 stores, each running its own EOQ policy with the same S and H. Roughly how much more total inventory does Adidas end up holding, versus Amazon?', '["About the same", "About 2x", "About 10x", "About 100x"]'::jsonb, 'About 10x', 'Session 10 — EOQ', 'Each Adidas store faces R/100, so its EOQ is sqrt(2(R/100)S/H) = Q_Amazon / 10 (the square root of the 100x demand cut). Total Adidas inventory is 100 stores x (Q_Amazon/10) = 10 x Q_Amazon. The square root is what keeps it at 10x rather than the naively-expected 100x.', 'EOQ scales with the square root of demand, not linearly -- work out Q for one store first, then multiply by 100 stores.', null, null, 2, 'prof_adapted', now()) on conflict (id) do nothing;

insert into public.learn_questions (id, course_code, type, topic, session, prompt, choices, correct_answer, source, explanation, hint, scenario_id, scenario_order, difficulty, provenance, created_at) values ('opm-f44', 'OPMG', 'formula', 'safety_stock_reorder_point', 10, 'Kristen''s Cookie Co.''s raw-material supplier has a 1.5-week lead time. Weekly demand averages 100 dozen with a standard deviation of 20 dozen (normally distributed), and Kristen wants a 99% service level (z = 2.326) against running out before the next delivery. What reorder point should she use?', '["150 dozen", "174 dozen", "207 dozen", "220 dozen"]'::jsonb, '207 dozen', 'Session 10 — Safety Stock', 'Lead-time demand is N(RL, sigma*sqrt(L)) = N(100 x 1.5, 20 x sqrt(1.5)) = N(150, 24.5). Safety stock = z x sigma x sqrt(L) = 2.326 x 24.5 ~= 57. ROP = 150 + 57 ~= 207 dozen. 150 dozen is the deterministic reorder point with no safety stock at all. 220 dozen comes from the common error of using sigma x L (69.8) instead of sigma x sqrt(L) -- standard deviations don''t scale linearly with time, variances do. 174 dozen comes from using z = 1 instead of the 99% value of 2.326.', 'Variances add over the lead time, not standard deviations -- the spread of lead-time demand is sigma x sqrt(L), never sigma x L.', null, null, 2, 'prof_adapted', now()) on conflict (id) do nothing;

insert into public.learn_questions (id, course_code, type, topic, session, prompt, choices, correct_answer, source, explanation, hint, scenario_id, scenario_order, difficulty, provenance, created_at) values ('opm-f45', 'OPMG', 'formula', 'safety_stock_reorder_point', 10, 'Fun Colors stocks 75 independent paint colours, each carrying its own safety stock at a 98% service level. It can instead mix any colour to order from one shared base-tone paint, same total demand, same lead time, same service level. By roughly what factor does its TOTAL safety stock shrink?', '["It doesn''t change", "About 2x", "About 8.7x", "About 75x"]'::jsonb, 'About 8.7x', 'Session 10 — Safety Stock', '75 separate colours need 75 x (z x sigma x sqrt(L)) of total safety stock. Pooled into one base tone, demand variance adds: the pooled sigma is sigma x sqrt(75), so pooled safety stock is z x sigma x sqrt(75) x sqrt(L) -- a factor of 75/sqrt(75) = sqrt(75) ~= 8.7 smaller than the sum of the 75 separate ones. The same square-root aggregation benefit as EOQ, applied to uncertainty instead of ordering cost.', 'Same mechanism as the Amazon-vs-Adidas EOQ question: pooling n independent, identical streams reduces the relevant total by a factor of sqrt(n), not n.', null, null, 3, 'prof_adapted', now()) on conflict (id) do nothing;

commit;
